func (s *UnpivotStage) Apply(in []*record.Record, stderr io.Writer, strict bool, stats *Stats) ([]*record.Record, error) {
	out := make([]*record.Record, 0, len(in))
	for _, r := range in {
		recs, err := s.processRecord(r)
		if err != nil {
			return nil, err
		}
		out = append(out, recs...)
	}
	return out, nil
}

func (s *UnpivotStage) processRecord(r *record.Record) ([]*record.Record, error) {
	var order []string
	var err error
	if s.useMatch {
		order, err = s.matchOrder(r)
	} else {
		order, err = s.explicitOrder(r)
	}
	if err != nil {
		return nil, err
	}

	out := make([]*record.Record, 0, len(order))
	for _, name := range order {
		present := r.Has(name)
		if !present {
			switch s.onMissing {
			case "skip":
				continue
			case "error":
				return nil, fmt.Errorf("flowctl: unpivot: missing measure column %s at row %d", name, r.InputRow)
			case "keep_empty":
			default:
				// configuration validation should prevent this.
			}
		}

		rendered := ""
		if present {
			raw, _ := r.Get(name)
			rendered, err = s.renderValue(raw, name, r.InputRow)
			if err != nil {
				return nil, err
			}
		}

		if s.dropEmpty && rendered == "" {
			continue
		}

		nr := record.New()
		nr.InputRow = r.InputRow
		for _, col := range s.id {
			if v, ok := r.Get(col); ok {
				nr.Set(col, v)
			} else {
				nr.Set(col, "")
			}
		}

		if s.useAxes {
			sub := s.re.FindStringSubmatch(name)
			for _, ax := range s.axes {
				cell := ""
				if sub != nil && ax.group < len(sub) {
					cell = sub[ax.group]
				}
				nr.Set(ax.name, cell)
			}
		} else {
			nr.Set(s.variable, s.stripVariableName(name))
		}
		nr.Set(s.value, rendered)

		out = append(out, nr)
	}
	return out, nil
}

func (s *UnpivotStage) explicitOrder(r *record.Record) ([]string, error) {
	if s.onMissing == "error" {
		for _, m := range s.measures {
			if !r.Has(m) {
				return nil, fmt.Errorf("flowctl: unpivot: missing measure column %s at row %d", m, r.InputRow)
			}
		}
	}

	order := []string{}
	if s.sortMode == "measure" {
		order = s.measures
		if s.onMissing != "keep_empty" {
			order = filterPresent(order, r)
		}
		return order, nil
	}

	for _, k := range r.Order {
		if s.measureSet[k] {
			order = append(order, k)
		}
	}
	if s.onMissing == "keep_empty" {
		for _, m := range s.measures {
			if !r.Has(m) {
				order = append(order, m)
			}
		}
	}
	return order, nil
}

func (s *UnpivotStage) matchOrder(r *record.Record) ([]string, error) {
	present := []string{}
	for _, k := range r.Order {
		if s.isMatch(k) {
			present = append(present, k)
			s.ensureFirstSeen(k)
		}
	}

	if s.onMissing == "error" {
		for _, m := range s.firstSeen {
			if !r.Has(m) {
				return nil, fmt.Errorf("flowctl: unpivot: missing measure column %s at row %d", m, r.InputRow)
			}
		}
	}

	order := []string{}
	if s.sortMode == "measure" {
		order = s.firstSeen
		if s.onMissing != "keep_empty" {
			order = filterPresent(order, r)
		}
		return order, nil
	}

	order = append(order, present...)
	if s.onMissing == "keep_empty" {
		for _, m := range s.firstSeen {
			if !r.Has(m) {
				order = append(order, m)
			}
		}
	}
	return order, nil
}

func (s *UnpivotStage) isMatch(col string) bool {
	if s.idSet[col] || s.excludeSet[col] {
		return false
	}
	if s.prefix != "" && !strings.HasPrefix(col, s.prefix) {
		return false
	}
	if s.suffix != "" && !strings.HasSuffix(col, s.suffix) {
		return false
	}
	if s.re != nil && !s.re.MatchString(col) {
		return false
	}
	return true
}

func (s *UnpivotStage) ensureFirstSeen(name string) {
	if !s.firstSeenSet[name] {
		s.firstSeenSet[name] = true
		s.firstSeen = append(s.firstSeen, name)
	}
}

func (s *UnpivotStage) renderValue(raw, name string, row int) (string, error) {
	switch s.valueType {
	case "pass", "string":
		return raw, nil
	case "number":
		if raw == "" {
			return "", nil
		}
		f, err := parseFloat(raw)
		if err != nil {
			return "", fmt.Errorf("flowctl: unpivot: non-numeric value in measure %s at row %d", name, row)
		}
		return formatFloat(f), nil
	default:
		return raw, nil
	}
}

func (s *UnpivotStage) stripVariableName(name string) string {
	out := name
	if s.stripPrefix != "" && strings.HasPrefix(out, s.stripPrefix) {
		out = strings.TrimPrefix(out, s.stripPrefix)
	}
	if s.stripSuffix != "" && strings.HasSuffix(out, s.stripSuffix) {
		out = strings.TrimSuffix(out, s.stripSuffix)
	}
	return out
}

func filterPresent(in []string, r *record.Record) []string {
	out := make([]string, 0, len(in))
	for _, m := range in {
		if r.Has(m) {
			out = append(out, m)
		}
	}
	return out
}

