func toInt(v interface{}) (int, bool, error) {
	switch n := v.(type) {
	case int:
		return n, true, nil
	case int64:
		return int(n), true, nil
	case float64:
		if n == float64(int(n)) {
			return int(n), true, nil
		}
		return 0, true, fmt.Errorf("not an integer")
	case string:
		n, err := strconv.Atoi(n)
		if err != nil {
			return 0, true, fmt.Errorf("not an integer")
		}
		return n, true, nil
	default:
		return 0, true, fmt.Errorf("not an integer")
	}
}
